package app.veyra;
import android.net.Uri;import androidx.media3.datasource.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class CaptionTiming {
 private static final Pattern TIMING=Pattern.compile("(?m)^(\\s*)(?:(\\d+):)?([0-5]\\d):([0-5]\\d)([.,])(\\d{3})([ \\t]+-->[ \\t]+)(?:(\\d+):)?([0-5]\\d):([0-5]\\d)([.,])(\\d{3})([^\\r\\n]*)$");
 static String shift(String text,int offsetMs){if(offsetMs< -10000||offsetMs>10000)throw new IllegalArgumentException("Caption offset out of range");Matcher matcher=TIMING.matcher(text);StringBuffer result=new StringBuffer();while(matcher.find()){try{long start=time(matcher,2),end=time(matcher,8);if(end<start)continue;String replacement=matcher.group(1)+stamp(Math.max(0,Math.addExact(start,offsetMs)),matcher.group(2)!=null,matcher.group(5).charAt(0))+matcher.group(7)+stamp(Math.max(0,Math.addExact(end,offsetMs)),matcher.group(8)!=null,matcher.group(11).charAt(0))+matcher.group(13);matcher.appendReplacement(result,Matcher.quoteReplacement(replacement));}catch(NumberFormatException|ArithmeticException ignored){}}matcher.appendTail(result);return result.toString();}
 private static long time(Matcher m,int hours){long h=m.group(hours)==null?0:Long.parseLong(m.group(hours));return Math.addExact(Math.multiplyExact(h,3600000L),Long.parseLong(m.group(hours+1))*60000+Long.parseLong(m.group(hours+2))*1000+Long.parseLong(m.group(hours+4)));}
 private static String stamp(long ms,boolean hours,char separator){long h=ms/3600000;return hours||h>0?String.format(Locale.ROOT,"%02d:%02d:%02d%c%03d",h,ms/60000%60,ms/1000%60,separator,ms%1000):String.format(Locale.ROOT,"%02d:%02d%c%03d",ms/60000,ms/1000%60,separator,ms%1000);}
 static DataSource.Factory factory(DataSource.Factory original,Set<String> captions,int offsetMs){if(offsetMs==0||captions.isEmpty())return original;return ()->new DataSource(){private DataSource live;private final List<TransferListener> listeners=new ArrayList<>();public void addTransferListener(TransferListener l){listeners.add(l);if(live!=null)live.addTransferListener(l);}public long open(DataSpec spec)throws IOException{if(captions.contains(spec.uri.toString())){DataSource network=original.createDataSource();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try{network.open(spec.buildUpon().setPosition(0).setLength(androidx.media3.common.C.LENGTH_UNSET).build());byte[] buffer=new byte[8192];int n;while((n=network.read(buffer,0,buffer.length))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(bytes.size()+n>2*1024*1024)throw new IOException("Caption file too large");bytes.write(buffer,0,n);}}finally{network.close();}live=new ByteArrayDataSource(shift(new String(bytes.toByteArray(),StandardCharsets.UTF_8),offsetMs).getBytes(StandardCharsets.UTF_8));}else live=original.createDataSource();for(TransferListener listener:listeners)live.addTransferListener(listener);return live.open(spec);}public int read(byte[] b,int o,int n)throws IOException{return live.read(b,o,n);}public Uri getUri(){return live==null?null:live.getUri();}public Map<String,List<String>> getResponseHeaders(){return live==null?Collections.emptyMap():live.getResponseHeaders();}public void close()throws IOException{if(live!=null){live.close();live=null;}}};}
}
